//
//   Branch 5c (ConfidenceGatedStep returns non-">>" non-EOS token):
//     ConfidenceGatedStep guarantees token is parser-valid for currentConstrainedOut.
//     AppendConstrainedToken extends currentConstrainedOut, preserving IsValidPrefix.
//     Invariant preserved.
//
//   Branch 5d (ConfidenceGatedStep returns eosToken):
//     Break. insideConstrainedOut and currentConstrainedOut unchanged.
//     Invariant preserved by loop invariant hypothesis.
//
// progress: |generated| <= |generatedPrefix| + steps
//
//   Branch 1 (UnconstrainedChunk): steps += stepsUsed, |newGenerated| <= |generated| + stepsUsed.
//     Bound preserved.
//
//   Branch 3 (OpenConstrainedSpan): steps += 1, appends "<<" (1 token). Bound preserved.
//
//   Branch 4 (CloseConstrainedSpan): steps += 1, appends ">>" (1 token). Bound preserved.
//
//   Branch 5a (">>" with IsCompletePrefix, CloseConstrainedSpan):
//     steps += 1, CloseConstrainedSpan appends ">>" (1 token). Bound preserved.
//
//   Branch 5b/5c (AppendConstrainedToken): steps += 1, appends 1 token. Bound preserved.
//
//   Branch 5d (EOS break): steps += 1, generated unchanged. Bound preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve math word problems step by step. For EVERY arithmetic expression and the final answer, wrap it in << >> delimiters. Example: The total is <<3 + 4>>. Final answer: <<7>>. Always wrap symbolic expressions in << >>.");

var steps: nat := 0;
var chunkSize: nat := 8;
var unconstrainedTokensSinceLastSpan: nat := 0;
var forceSpanThreshold: nat := 50;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if unconstrainedTokensSinceLastSpan >= forceSpanThreshold && steps + 1 <= maxSteps {
      var openGenerated, openInside, openCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openGenerated;
      insideConstrainedOut := openInside;
      currentConstrainedOut := openCurrent;
      steps := steps + 1;
      unconstrainedTokensSinceLastSpan := 0;
    } else {
      var remaining := maxSteps - steps;
      var chunkMax := if remaining < chunkSize then remaining else chunkSize;
      if chunkMax == 0 {
        break;
      }
      var newGenerated, stoppedOnOpenSpan, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(
        lm, prompt, generated, chunkMax, "<<", eosToken
      );
      steps := steps + stepsUsed;
      generated := newGenerated;
      unconstrainedTokensSinceLastSpan := unconstrainedTokensSinceLastSpan + stepsUsed;
      if stoppedOnEos {
        break;
      } else if stoppedOnOpenSpan {
        var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := enteredGenerated;
        insideConstrainedOut := enteredInside;
        currentConstrainedOut := enteredCurrent;
        unconstrainedTokensSinceLastSpan := 0;
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next, wasConstrained := helpers.ConfidenceGatedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else if next == ">>" && parser.IsCompletePrefix(currentConstrainedOut) {
      // The span is already complete; close it without appending ">>" first
      // (CloseConstrainedSpan will append ">>" itself)
      var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := closedGenerated;
      insideConstrainedOut := closedInside;
      currentConstrainedOut := closedCurrent;
    } else {
      // For ">>" when not complete, or any other valid token: append normally
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;
  }
}
